  function matchHotkey(e, def) {
    if (!def) return false;
    if (!!def.shift !== e.shiftKey) return false;
    if (!!def.ctrl  !== e.ctrlKey)  return false;
    if (!!def.alt   !== e.altKey)   return false;
    return (e.key || "").toLowerCase() === def.key.toLowerCase();
  }
  function ensureVisible(x, y, w, h, pad = 8) {
    return { x: clamp(x, pad, window.innerWidth - w - pad), y: clamp(y, pad, window.innerHeight - h - pad) };
  }
  function tryParseJSON(raw) { try { return JSON.parse(raw); } catch { return null; } }

    function sanitizeUrl(u, fallback) {
    try{
      const s = String(u || "").trim();
      if (!s) return fallback;
      const U = new URL(s, location.href);
      if (U.protocol !== "http:" && U.protocol !== "https:") return fallback;
      return U.href;
    }catch{
      return fallback;
    }
  }
  function cssUrl(u) {
    // minimál védelem: ne tudjon idézőjelet / sortörést “kiszúrni” a CSS-be
    return String(u || "").replace(/["\\\n\r]/g, "");
  }
  function sanitizeFontDataUrl(u) {
    const s = String(u || "").trim().replace(/[\n\r]/g, "");
    if (s.length > 5_500_000) return "";
    if (!/^data:/i.test(s)) return "";
    const head = s.slice(0, 96).toLowerCase();
    if (!/font|woff|ttf|otf|octet-stream|sfnt/.test(head)) return "";
    return s;
  }
  function sanitizeFontFamilyName(f) {
    return String(f || "").trim().replace(/['"<>;{}:\\]/g, "").slice(0, 120);
  }

  // Keep browser-local background images small enough for localStorage.
  function sanitizeImageDataUrl(u, maxLength = 1_650_000) {
    const s = String(u || "").trim().replace(/[\n\r]/g, "");
    if (s.length > maxLength) return "";
    if (!/^data:image\/(?:png|jpe?g|webp);base64,/i.test(s)) return "";
    return s;
  }

  const AD_CORE_SKIN_BG_MAX_DATA_URL_LENGTH = 3_500_000;
  let adCoreSkinBgSanitizeSource = null;
  let adCoreSkinBgSanitizeValue = "";
  let adCoreSkinBgRuntimeSource = "";
  let adCoreSkinBgRuntimeUrl = "";

  function sanitizeSkinBackgroundDataUrl(u) {
    if (u === adCoreSkinBgSanitizeSource) return adCoreSkinBgSanitizeValue;
    adCoreSkinBgSanitizeSource = u;
    adCoreSkinBgSanitizeValue = sanitizeImageDataUrl(u, AD_CORE_SKIN_BG_MAX_DATA_URL_LENGTH);
    return adCoreSkinBgSanitizeValue;
  }

  function clearSkinBackgroundRuntimeUrl() {
    if (adCoreSkinBgRuntimeUrl) {
      try { URL.revokeObjectURL(adCoreSkinBgRuntimeUrl); } catch (_) {}
    }
    adCoreSkinBgRuntimeSource = "";
    adCoreSkinBgRuntimeUrl = "";
  }

  function skinBackgroundRuntimeUrl(u) {
    const safe = sanitizeSkinBackgroundDataUrl(u);
    if (!safe) {
      clearSkinBackgroundRuntimeUrl();
      return "";
    }
    if (safe === adCoreSkinBgRuntimeSource && adCoreSkinBgRuntimeUrl) {
      return adCoreSkinBgRuntimeUrl;
    }

    clearSkinBackgroundRuntimeUrl();
    try {
      const match = safe.match(/^data:([^;,]+);base64,(.+)$/i);
      if (!match) return safe;
      const binary = atob(match[2]);
      const bytes = new Uint8Array(binary.length);
      for (let index = 0; index < binary.length; index += 1) {
        bytes[index] = binary.charCodeAt(index);
      }
      adCoreSkinBgRuntimeUrl = URL.createObjectURL(new Blob([bytes], { type: match[1] }));
      adCoreSkinBgRuntimeSource = safe;
      return adCoreSkinBgRuntimeUrl;
    } catch (_) {
      adCoreSkinBgRuntimeSource = safe;
      adCoreSkinBgRuntimeUrl = safe;
      return safe;
    }
  }

  window.addEventListener("pagehide", clearSkinBackgroundRuntimeUrl, { once: true });

  function readFileAsDataUrl(file) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onerror = () => reject(new Error("read"));
      reader.onload = () => typeof reader.result === "string" ? resolve(reader.result) : reject(new Error("read"));
      reader.readAsDataURL(file);
    });
  }

  function loadImageFromDataUrl(dataUrl) {
    return new Promise((resolve, reject) => {
      const image = new Image();
      image.onload = () => resolve(image);
      image.onerror = () => reject(new Error("image"));
      image.src = dataUrl;
    });
  }

  // General stored-image compaction is intentionally kept conservative for
  // custom boards and surrounds. Their older 1920px / 1.5M data-URL budget is
  // left untouched so previously safe localStorage usage does not regress.
  async function compactBackgroundImage(file) {
    if (!file || !/^image\/(?:png|jpe?g|webp)$/i.test(String(file.type || ""))) {
      throw new Error("type");
    }
    const image = await loadImageFromDataUrl(await readFileAsDataUrl(file));
    const sourceW = Math.max(1, Number(image.naturalWidth || image.width || 1));
    const sourceH = Math.max(1, Number(image.naturalHeight || image.height || 1));
    let scale = Math.min(1, 1920 / Math.max(sourceW, sourceH));

    for (let attempt = 0; attempt < 8; attempt += 1) {
      const width = Math.max(1, Math.round(sourceW * scale));
      const height = Math.max(1, Math.round(sourceH * scale));
      const canvas = document.createElement("canvas");
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext("2d", { alpha: true });
      if (!ctx) throw new Error("canvas");
      ctx.imageSmoothingEnabled = true;
      ctx.imageSmoothingQuality = "high";
      ctx.drawImage(image, 0, 0, width, height);
      const quality = Math.max(0.48, 0.86 - attempt * 0.055);
      let packed = canvas.toDataURL("image/webp", quality);
      if (!/^data:image\/webp/i.test(packed)) packed = canvas.toDataURL("image/jpeg", quality);
      if (packed.length <= 1_500_000) return packed;
      scale *= 0.82;
    }
    throw new Error("size");
  }

  // v1089: screen backgrounds need a separate quality path. The previous shared
  // compactor always reduced a 2560x1440 image to 1920x1080 (or below) before
  // CSS enlarged it back to the viewport. That was the direct source of blur.
  // The asset remains browser-local because it is still saved in the CORE state.
  async function compactSkinBackgroundImage(file, acceptCandidate = null) {
    if (!file || !/^image\/(?:png|jpe?g|webp)$/i.test(String(file.type || ""))) {
      throw new Error("type");
    }
    const sourceDataUrl = await readFileAsDataUrl(file);
    const image = await loadImageFromDataUrl(sourceDataUrl);
    const sourceW = Math.max(1, Number(image.naturalWidth || image.width || 1));
    const sourceH = Math.max(1, Number(image.naturalHeight || image.height || 1));
    const maxLongEdge = 2560;
    const maxDataUrlLength = AD_CORE_SKIN_BG_MAX_DATA_URL_LENGTH;
    const offerCandidate = (candidate) => {
      const safe = sanitizeImageDataUrl(candidate, maxDataUrlLength);
      if (!safe) return "";
      if (typeof acceptCandidate !== "function") return safe;
      return acceptCandidate(safe) ? safe : "";
    };

    // Preserve an already suitable WQHD source byte-for-byte. Re-encoding an
    // image that already fits the viewport can only discard detail.
    if (Math.max(sourceW, sourceH) <= maxLongEdge && sourceDataUrl.length <= maxDataUrlLength) {
      const accepted = offerCandidate(sourceDataUrl);
      if (accepted) return accepted;
    }

    let scale = Math.min(1, maxLongEdge / Math.max(sourceW, sourceH));

    // First reduce encoded file size while retaining 2560px. Resolution is
    // stepped down only if the browser still rejects the stored CORE state.
    for (let attempt = 0; attempt < 14; attempt += 1) {
      const width = Math.max(1, Math.round(sourceW * scale));
      const height = Math.max(1, Math.round(sourceH * scale));
      const canvas = document.createElement("canvas");
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext("2d", { alpha: true });
      if (!ctx) throw new Error("canvas");
      ctx.imageSmoothingEnabled = true;
      ctx.imageSmoothingQuality = "high";
      ctx.drawImage(image, 0, 0, width, height);

      // A high initial quality protects fine lines and rendered text in a 1440p
      // background. Only an unusually detailed / noisy source is stepped down.
      const quality = Math.max(0.62, 0.94 - attempt * 0.035);
      let packed = canvas.toDataURL("image/webp", quality);
      if (!/^data:image\/webp/i.test(packed)) packed = canvas.toDataURL("image/jpeg", quality);
      const accepted = offerCandidate(packed);
      if (accepted) return accepted;
      if (attempt >= 4) scale *= 0.90;
    }
    throw new Error(typeof acceptCandidate === "function" ? "storage" : "size");
  }

  function chooseUploadedBackgroundImage() {
    const input = document.createElement("input");
    input.type = "file";
    input.accept = ".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp";
    input.style.display = "none";
    document.body.appendChild(input);
    input.addEventListener("change", async () => {
      const file = input.files?.[0];
      const c = cfg();
      const previous = String(c.SKIN_BG_DATA_URL || "");
      try {
        if (!file) return;
        const dataUrl = await compactSkinBackgroundImage(file, (candidate) => {
          c.SKIN_BG_DATA_URL = candidate;
          try {
            state.schemaVersion = STATE_SCHEMA_VERSION;
            localStorage.setItem(STORE_KEY_STATE, JSON.stringify(state));
            return true;
          } catch (_) {
            return false;
          }
        });
        if (!dataUrl) throw new Error("storage");
        dirtySkin();
        scheduleUpdate();
        renderPanelIfOpen();
        showToast(T().saved || "Saved ✓");
      } catch (err) {
        c.SKIN_BG_DATA_URL = previous;
        const message = err?.message === "type"
          ? "Csak JPG, PNG vagy WebP kép tölthető fel."
          : (err?.message === "storage" || err?.message === "size")
            ? "A kép az automatikus optimalizálás után sem fér el a böngésző helyi tárhelyén. Törölj egy korábbi feltöltött képet valamelyik presetből."
            : "A háttérkép feldolgozása nem sikerült.";
        alert(message);
      } finally {
        try { input.remove(); } catch (_) {}
      }
    }, { once: true });
    input.click();
  }

