  scoreSize.addEventListener("change", () => showToast(L.saved));

 const nameRowSize = document.createElement("input");
nameRowSize.type = "range";
nameRowSize.min = "0.60";
const nameSliderMax = layoutPanelCurrentlyOn
  ? 1.80
  // Layout OFF: v21 stabil kártyaállapotból számolt biztonságos felső határ.
  : 1.80;
nameRowSize.max = String(nameSliderMax);
nameRowSize.step = "0.02";
bindLayoutPanelRangeDrag(nameRowSize);
nameRowSize.value = String(clamp(Number(c.LAYOUT_NAME_ROW_SCALE ?? 1), 0.60, nameSliderMax));

const nameRow0 = Number(nameRowSize.value);
const nameRowSizeRow = mkSliderRow(
  LT.nameRowSize || "Név sor mérete",
  nameRowSize,
  `${Math.round(nameRow0 * 100)}%`,
  "ok",
  compact
);
box.appendChild(nameRowSizeRow.row);

nameRowSize.addEventListener("input", () => {
  c.LAYOUT_NAME_ROW_SCALE = clamp(Number(nameRowSize.value) || 1, 0.60, nameSliderMax);
  nameRowSizeRow.setPill(`${Math.round(c.LAYOUT_NAME_ROW_SCALE * 100)}%`, "ok");
  saveStateDebounced();
  dirtyPlayers();
  scheduleUpdate();
});
nameRowSize.addEventListener("change", () => showToast(L.saved));

const avgRowSize = document.createElement("input");
avgRowSize.type = "range";
avgRowSize.min = "0.60";
const avgSliderMax = 2.40;

  if (!layoutPanelCurrentlyOn) {
    let offClamped = false;
    const sc0 = Number(c.LAYOUT_SCORE_FONT_PX ?? 100);
    const nm0 = Number(c.LAYOUT_NAME_ROW_SCALE ?? 1);
    const av0 = Number(c.LAYOUT_AVG_ROW_SCALE ?? 1);
    if (Number.isFinite(sc0) && sc0 > scoreSliderMax) { c.LAYOUT_SCORE_FONT_PX = scoreSliderMax; offClamped = true; }
    if (Number.isFinite(nm0) && nm0 > nameSliderMax) { c.LAYOUT_NAME_ROW_SCALE = nameSliderMax; offClamped = true; }
    if (Number.isFinite(av0) && av0 > avgSliderMax) { c.LAYOUT_AVG_ROW_SCALE = avgSliderMax; offClamped = true; }
    if (offClamped) { saveStateDebounced(); dirtyPlayers(); scheduleUpdate(); }
  }

avgRowSize.max = String(avgSliderMax);
avgRowSize.step = "0.02";
bindLayoutPanelRangeDrag(avgRowSize);
avgRowSize.value = String(clamp(finiteNumberOr(c.LAYOUT_AVG_ROW_SCALE, 1), 0.60, avgSliderMax));

const avgRow0 = finiteNumberOr(avgRowSize.value, 1);
