  adCoreV1106EnsureNativeSpecialStyle();

  /* ---------- v1106: complete native identity row in 3+ player view ---------- */
  const AD_CORE_V1106_MULTI_STYLE_ID = 'ad-core-v1106-complete-multiplayer-identity-row';
  const AD_CORE_V1106_ROW_ATTR = 'data-ad-core-v1106-identity-row';
  const AD_CORE_V1106_BRANCH_ATTR = 'data-ad-core-v1106-name-branch';
  const AD_CORE_V1106_AVATAR_ATTR = 'data-ad-core-v1106-avatar-visible';
