      if (!leaves.length) return;
      const token = adCoreV1103SpecialToken(leaves[0].textContent);
      if (!CHECKOUT_TOKEN_RE.test(token)) return;

      const kind = adCoreV1104SpecialKind(card) === 'checkout' ? 'checkout' : 'tip';
      card.dataset.adCoreV1016Kind = kind;
      activeCards.add(card);
      adCoreV1107PaintSpecialCard(card, kind);

