      adCoreV1097SetImportantStyle(overlay, 'font-family', 'var(--ad-turn-card-font, inherit)');
      adCoreV1097SetImportantStyle(overlay, 'transform', 'none');
      adCoreV1097SetImportantStyle(overlay, 'translate', 'none');
